<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{login}from'@whaashop/shared';import BrandLogo from'../components/BrandLogo.vue';const username=ref('admin'),password=ref('password'),error=ref(''),router=useRouter();async function submit(){try{const u=await login(username.value,password.value);if(u.role!=='ADMIN')throw new Error('该账号不是管理员');router.push('/')}catch(e){error.value=(e as Error).message}}</script>
<template><div style="max-width:400px;margin:12vh auto" class="panel"><BrandLogo tagline="ADMIN CONSOLE"/><h1 style="color:#1d6fba;margin-bottom:8px">管理后台</h1><p style="color:#6b8ba5">使用管理员账号登录运营中心</p><el-input v-model="username" placeholder="用户名"/><el-input v-model="password" type="password" placeholder="密码" style="margin:14px 0"/><el-alert v-if="error" :title="error" type="error"/><el-button type="primary" style="width:100%;margin-top:14px" @click="submit">登录</el-button></div></template>
